# cg-testkit Integration: T-ENG-100-107 + T-CGUAS-001-003
# Ausfuehren: Set-ExecutionPolicy -Scope Process Bypass
#             & "$env:USERPROFILE\Downloads\cg-testkit-integrate.ps1"

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$TESTKIT   = "C:\Users\bauer\OneDrive\Desktop\chronogrid-impl\monorepo\packages\cg-testkit\src"
$ENG_FILE  = "$TESTKIT\suites\t-eng.ts"
$CLI_FILE  = "$TESTKIT\cli.ts"
$CGUAS_OUT = "$TESTKIT\suites\t-cguas.ts"
$MONOREPO  = "C:\Users\bauer\OneDrive\Desktop\chronogrid-impl\monorepo"

function Write-Step($n, $msg) { Write-Host ""; Write-Host "[$n] $msg" -ForegroundColor Cyan }
function Write-OK($msg)        { Write-Host "    OK  $msg" -ForegroundColor Green }
function Write-SKIP($msg)      { Write-Host "    --  $msg (uebersprungen)" -ForegroundColor Yellow }

# ================================================================
# SCHRITT 1: t-cguas.ts schreiben (base64-dekodiert, kein Escaping)
# ================================================================
Write-Step 1 "Erstelle t-cguas.ts"
$b64cguas = ""
$bytes = [System.Convert]::FromBase64String($b64cguas)
[System.IO.File]::WriteAllBytes($CGUAS_OUT, $bytes)
Write-OK "t-cguas.ts geschrieben ($($bytes.Length) Bytes, 11 Tests: T-CGUAS-001a bis 003e)"

# ================================================================
# SCHRITT 2: t-eng.ts patchen
# ================================================================
Write-Step 2 "Patche t-eng.ts"
$engContent = [System.IO.File]::ReadAllText($ENG_FILE, [System.Text.Encoding]::UTF8)

if ($engContent -match 'T_ENG_CGUA') {
    Write-SKIP "t-eng.ts bereits gepatcht"
} else {
    # 2a: cg-cguas Imports nach letztem import-Block einfuegen
    $cgImport = "`nimport { CGUAS_MAX, isCGUAValid, cgua_safeAdd, toCGUA, cgua_toCGTA, parseCGTA_CGUAS } from 'cg-cguas/cguas.js';"
    # Ersetze erste Leerzeile nach einem Import-Block-Ende
    $engContent = [regex]::Replace($engContent,
        "(from '[^']+';)(`n`n)",
        { param($m) $m.Groups[1].Value + $cgImport + $m.Groups[2].Value },
        [System.Text.RegularExpressions.RegexOptions]::None)

    # 2b: T_ENG_CGUA-Block vor ALL_T_ENG einfuegen (base64-dekodiert)
    $b64add = ""
    $addText = [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64add))
    $engContent = [regex]::Replace($engContent,
        '(export const ALL_T_ENG)',
        $addText.Replace('$', '`$') + "`n`$1")

    # 2c: ...T_ENG_CGUA am Ende von ALL_T_ENG vor ]; einfuegen
    $engContent = [regex]::Replace($engContent,
        '(\.\.\.(T_BIG)[^\]]*?)(`n\s*\];)',
        { param($m) $m.Groups[1].Value + ",`n  ...T_ENG_CGUA," + $m.Groups[3].Value })

    [System.IO.File]::WriteAllText($ENG_FILE, $engContent, [System.Text.Encoding]::UTF8)
    Write-OK "t-eng.ts gepatcht (20 neue Tests: T-ENG-100 bis T-ENG-CGUA-DET-4)"
}

# ================================================================
# SCHRITT 3: cli.ts patchen
# ================================================================
Write-Step 3 "Patche cli.ts"
$cliContent = [System.IO.File]::ReadAllText($CLI_FILE, [System.Text.Encoding]::UTF8)

if ($cliContent -match 'ALL_T_CGUAS') {
    Write-SKIP "cli.ts bereits gepatcht"
} else {
    # 3a: Import nach ucTests-Import einfuegen
    $cliContent = [regex]::Replace($cliContent,
        "(import\{ucTests\}from'\./suites/t-uc\.js';)",
        { param($m) $m.Groups[1].Value + "import{ALL_T_CGUAS}from'./suites/t-cguas.js';" })

    # 3b: ...ALL_T_CGUAS vor das schliessende ] von allTests einfuegen
    $cliContent = [regex]::Replace($cliContent,
        '(\.\.\.(ucTests|apiTests|authTests))(\s*\])',
        { param($m) $m.Groups[1].Value + ',...ALL_T_CGUAS' + $m.Groups[3].Value })

    [System.IO.File]::WriteAllText($CLI_FILE, $cliContent, [System.Text.Encoding]::UTF8)
    Write-OK "cli.ts gepatcht (Import + ALL_T_CGUAS in allTests)"
}

# ================================================================
# SCHRITT 4: pnpm test:level2
# ================================================================
Write-Step 4 "Fuehre pnpm test:level2 aus"
Set-Location $MONOREPO
pnpm test:level2

if ($LASTEXITCODE -eq 0) {
    Write-Host ""
    Write-Host "================================================================" -ForegroundColor Green
    Write-Host "  ALLE TESTS GRUEN" -ForegroundColor Green
    Write-Host "  T-ENG-100-107 + T-CGUAS-001-003 im normativen Harness aktiv." -ForegroundColor Green
    Write-Host "================================================================" -ForegroundColor Green
} else {
    Write-Host "Tests fehlgeschlagen (Exit $LASTEXITCODE)" -ForegroundColor Red
    exit 1
}
